import itertools
def maps7to3():
    # all monotone surjective maps from 0..6 to 0..2 (bins sizes 2,3,2 in some order)
    outs=[]
    for sizes in itertools.permutations([2,3,2]):
        m=[];v=0
        for s in sizes:
            m+= [v]*s; v+=1
        outs.append(tuple(m))
    return set(outs)
